{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"Landlords may terminate a tenancy only for the ordinance's at-fault or no-fault just causes and must pay relocation assistance for no-fault evictions; non-payment eviction requires rent owed above the Fair Market Rent.","key_value":"6 months' tenancy or expired lease","coverage_conditions":"Most City of Los Angeles residential rentals not regulated by the RSO; tenant must have lived in the unit at least six months or their original lease expired; applies to buildings newer than October 1, 1978 and to single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":"1978-10-01","date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":true,"other":"Applies to single-family dwellings; RSO-regulated units not covered"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, certain cooperatives, some nonprofit homeless facilities and short-term substance-abuse treatment centers, and HACLA or government-owned properties.","penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"JCO covers units not regulated by the City's Rent Stabilization Ordinance; the state AB 1482 exemption for single-family homes does not exempt them from the JCO.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"Annual rent increases on covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; the maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% (Aug 1, 2024-Jul 31, 2025)","coverage_conditions":"Buildings older than 15 years that are not subject to the City's RSO; the exemption is rolling, so units become covered as they age past 15 years.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Rolling 15-year construction cutoff; two-unit owner-occupied and qualifying single-family homes/condos exempt"},"exemptions":"Units constructed within the last 15 years, deed- or regulatory-restricted affordable units, certain dormitories, a two-unit property with an owner-occupied second unit, qualifying single-family homes and condominiums, and units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"The City's JCO does not regulate rent increases; this state cap exempts units already subject to the City's RSO.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
